// Logotipo Oficial H. Ayuntamiento de Coatzacoalcos 2026-2029
// Dirección de Salud Pública Municipal
// Escudo Oficial + C Nos Va Muy Bien Coatza (Fiel a la papelería oficial)

const LOGO_BASE64 = '';

function obtenerLogoHtml({ height = 55, maxWidth = 340, style = '' } = {}) {
  return `
    <div class="logo-institucional-bloque" style="display: inline-flex; align-items: center; gap: 12px; margin-top: 4px;">
      <img src="data:image/png;base64,${LOGO_BASE64}" style="height: ${height}px; max-width: ${maxWidth}px; object-fit: contain; ${style}" alt="Gobierno de Coatzacoalcos 2026-2029">
      <div class="logo-texto-dept" style="font-size: 9px; font-weight: bold; color: #701128; line-height: 1.25; text-transform: uppercase; border-left: 2px solid #b38e5d; padding-left: 9px; text-align: left;">
        DIRECCIÓN DE<br>SALUD PÚBLICA<br>MUNICIPAL
      </div>
    </div>
  `;
}

function obtenerLogoCoatzacoalcosHtml(opts) {
  return obtenerLogoHtml(opts);
}

module.exports = {
  obtenerLogoCoatzacoalcosHtml,
  LOGO_BASE64,
  obtenerLogoHtml
};
